// Created: 2026-07-26

/**
 * Unit tests for context-file-budget-guard hook
 *
 * Guards MEMORY.md / CLAUDE.md against writes that push them over their
 * per-session byte budgets. ASK when the projected post-write size crosses
 * the budget; silent pass otherwise. Edit projection must read-and-apply
 * the diff (a plain delta is wrong for replace_all / multi-occurrence).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import { contextFileBudgetGuard } from '../../pretool/write-edit/context-file-budget-guard.js';

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'budget-guard-'));
  delete process.env.ORK_CONTEXT_FILE_BUDGET_BYTES;
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  delete process.env.ORK_CONTEXT_FILE_BUDGET_BYTES;
});

function writeInput(file_path: string, content: string): HookInput {
  return {
    tool_name: 'Write',
    session_id: 'test-session',
    project_dir: dir,
    tool_input: { file_path, content },
  } as HookInput;
}

function editInput(
  file_path: string,
  old_string: string,
  new_string: string,
  replace_all = false,
): HookInput {
  return {
    tool_name: 'Edit',
    session_id: 'test-session',
    project_dir: dir,
    tool_input: { file_path, old_string, new_string, replace_all },
  } as HookInput;
}

function isAsk(result: ReturnType<typeof contextFileBudgetGuard>): boolean {
  const out = result.hookSpecificOutput as { permissionDecision?: string } | undefined;
  return out?.permissionDecision === 'ask';
}

describe('context-file-budget-guard', () => {
  it('passes non-guarded files silently regardless of size', () => {
    const big = 'x'.repeat(100 * 1024);
    const result = contextFileBudgetGuard(writeInput(join(dir, 'notes.md'), big));
    expect(isAsk(result)).toBe(false);
    expect(result.continue).toBe(true);
  });

  it('passes a small MEMORY.md write silently', () => {
    const result = contextFileBudgetGuard(writeInput(join(dir, 'MEMORY.md'), 'small index\n'));
    expect(isAsk(result)).toBe(false);
  });

  it('ASKs when a Write pushes MEMORY.md over 17KB', () => {
    const over = 'y'.repeat(18 * 1024);
    const result = contextFileBudgetGuard(writeInput(join(dir, 'MEMORY.md'), over));
    expect(isAsk(result)).toBe(true);
  });

  it('ASKs when a Write pushes CLAUDE.md over 20KB', () => {
    const over = 'y'.repeat(21 * 1024);
    const result = contextFileBudgetGuard(writeInput(join(dir, 'CLAUDE.md'), over));
    expect(isAsk(result)).toBe(true);
  });

  it('passes CLAUDE.md between 17KB and 20KB (budgets are per-file)', () => {
    const mid = 'y'.repeat(18 * 1024);
    const result = contextFileBudgetGuard(writeInput(join(dir, 'CLAUDE.md'), mid));
    expect(isAsk(result)).toBe(false);
  });

  it('projects Edit size by applying the diff, not by delta', () => {
    // File just under budget; the edit's new_string is small but the
    // replacement expands one occurrence enough to cross the line.
    const filePath = join(dir, 'MEMORY.md');
    const base = `HEADER\n${'z'.repeat(17 * 1024 - 100)}`;
    writeFileSync(filePath, base);
    const result = contextFileBudgetGuard(
      editInput(filePath, 'HEADER', `HEADER${'w'.repeat(200)}`),
    );
    expect(isAsk(result)).toBe(true);
  });

  it('projects replace_all correctly (every occurrence counts)', () => {
    const filePath = join(dir, 'MEMORY.md');
    // 100 occurrences of a marker; each grows by 160 bytes on replace_all.
    const base = `${Array.from({ length: 100 }, () => 'MARK\n').join('')}${'z'.repeat(1024)}`;
    writeFileSync(filePath, base);
    const result = contextFileBudgetGuard(
      editInput(filePath, 'MARK', `MARK${'w'.repeat(160)}`, true),
    );
    // 100 * 160 = 16000 extra bytes + ~1.5KB base ≈ 17.5KB -> over
    expect(isAsk(result)).toBe(true);

    // Single-occurrence replace of the same strings stays under: proves the
    // projection distinguishes replace_all from single replace.
    const single = contextFileBudgetGuard(
      editInput(filePath, 'MARK', `MARK${'w'.repeat(160)}`, false),
    );
    expect(isAsk(single)).toBe(false);
  });

  it('fails open when the Edit target does not exist', () => {
    const result = contextFileBudgetGuard(
      editInput(join(dir, 'MEMORY.md'), 'absent', 'replacement'),
    );
    expect(isAsk(result)).toBe(false);
    expect(result.continue).toBe(true);
  });

  it('fails open when old_string is not present in the file', () => {
    const filePath = join(dir, 'MEMORY.md');
    writeFileSync(filePath, 'actual content');
    const result = contextFileBudgetGuard(
      editInput(filePath, 'not-in-file', 'x'.repeat(30 * 1024)),
    );
    expect(isAsk(result)).toBe(false);
  });

  it('respects ORK_CONTEXT_FILE_BUDGET_BYTES override', () => {
    process.env.ORK_CONTEXT_FILE_BUDGET_BYTES = '100';
    const result = contextFileBudgetGuard(writeInput(join(dir, 'MEMORY.md'), 'x'.repeat(200)));
    expect(isAsk(result)).toBe(true);

    process.env.ORK_CONTEXT_FILE_BUDGET_BYTES = String(1024 * 1024);
    const relaxed = contextFileBudgetGuard(writeInput(join(dir, 'MEMORY.md'), 'x'.repeat(30 * 1024)));
    expect(isAsk(relaxed)).toBe(false);
  });

  it('measures bytes, not characters (multi-byte content)', () => {
    // 9000 × '🧠' (4 bytes each) = 36KB of bytes but only 9000 code points.
    const emoji = '🧠'.repeat(9000);
    const result = contextFileBudgetGuard(writeInput(join(dir, 'MEMORY.md'), emoji));
    expect(isAsk(result)).toBe(true);
  });

  it('handles missing file_path without throwing', () => {
    const input = {
      tool_name: 'Write',
      session_id: 'test-session',
      project_dir: dir,
      tool_input: {},
    } as HookInput;
    const result = contextFileBudgetGuard(input);
    expect(result.continue).toBe(true);
  });
});
